374	// Deferred availability transport, not hot-follow authority: only byte-for-byte
375	// copies of creator-published AHE/snapshot storage are delivered. The receiver's
376	// ordinary room reopen still checks pinned genesis, published floor, closure,
377	// snapshot, signatures and projection. Its issuance/journal are NEVER copied.
378	async function transferDatabase(sourceName: string, targetName: string): Promise<void> {
379		const source = await request(indexedDB.open(sourceName));
380		try {
381			const names = [...source.objectStoreNames];
382			const reading = source.transaction(names, "readonly");
383			const rows = await Promise.all(
384				names.map(async (name) => {
385					const owner = reading.objectStore(name);
386					const indexes = [...owner.indexNames].map((indexName) => {
387						const index = owner.index(indexName);
388						return { name: index.name, keyPath: index.keyPath, unique: index.unique, multiEntry: index.multiEntry };
389					});
390					return {
391						name,
392						keyPath: owner.keyPath,
393						autoIncrement: owner.autoIncrement,
394						indexes,
395						keys: await request(owner.getAllKeys()),
396						values: await request(owner.getAll()),
397					};
398				})
399			);
400			const opening = indexedDB.open(targetName, source.version);
401			opening.onupgradeneeded = () => {
402				for (const row of rows)
403					if (!opening.result.objectStoreNames.contains(row.name)) {
404						const owner = opening.result.createObjectStore(row.name, {
405							keyPath: row.keyPath,
406							autoIncrement: row.autoIncrement,
407						});
408						for (const index of row.indexes)
409							owner.createIndex(index.name, index.keyPath, {
410								unique: index.unique,
411								multiEntry: index.multiEntry,
412							});
413					}
414			};
415			const target = await request(opening);
416			try {
417				const writing = target.transaction(names, "readwrite");
418				const complete = transactionDone(writing);
419				for (const row of rows) {
420					const owner = writing.objectStore(row.name);
421					owner.clear();
422					row.values.forEach((value, index) => {
423						if (row.keyPath === null) owner.put(structuredClone(value), row.keys[index]);
424						else owner.put(structuredClone(value));
425					});
426				}
427				await complete;
428			} finally {
429				target.close();
430			}
431		} finally {
432			source.close();
433		}
434	}
