467	function floorOwner() {
468		let state: V3RoomHeadState | null = null;
469		const result = () => ({ ok: true as const, state: structuredClone(state) });
470		const same = (value: unknown) => hex(encodeCanonical(value)) === hex(encodeCanonical(state));
471		const authority: CreateV3RoomSessionInput["roomHeadAuthority"] = {
472			initialization: { kind: "create" },
473			read: () => Promise.resolve(result()),
474			create: async (input) => {
475				await Promise.resolve();
476				if (state === null) state = { pending: null, stable: input.stable };
477				return result();
478			},
479			migrate: () => Promise.resolve({ ok: false, reason: "conflict" }),
480			begin: async (input) => {
481				await Promise.resolve();
482				if (!same(input.expected)) return { ok: false, reason: "conflict" };
483				const previous = required(state).stable;
484				state = { stable: previous, pending: { previous, next: input.next } };
485				return result();
486			},
487			commit: async (input) => {
488				await Promise.resolve();
489				if (!same(input.expected)) return { ok: false, reason: "conflict" };
490				state = { stable: required(required(state).pending).next, pending: null };
491				return result();
492			},
493		};
494		return {
495			authority,
496			read: () => structuredClone(required(state)),
497			// Transport the exact floor already committed by the genuine creator.
498			receive: (published: V3RoomHeadState) => {
499				state = structuredClone(published);
500			},
501		};
502	}
