854	async function durable(peer: Peer) {
855		const store = await createBrowserDurableIssuanceStore({ primaryDatabaseName: peer.databaseName });
856		try {
857			const scope = { author: peer.author, objectId: peer.input.objectId };
858			const lineage = await store.readLineage(scope);
