			proposed.candidates.filter(({ bytes }) =>
				["drp-creator-issuance-retirement-state", "drp-creator-author-issuance-frontiers-state"].includes(
					String(record(bytes).kind)
				)
			),
			"F5B_NO_LEGACY_CONTROLS"
